template:
% 参数由系统自动注入：\def\radius{3} \def\anglea{150} \def\angleb{340} \def\pratio{0.45} \def\chorddir{60} \def\showsimilar{0} \def\showangle{0} \def\showcenter{0} \def\labela{A} \def\labelb{B} \def\labelc{C} \def\labeld{D} \def\labelp{P}
% 视觉归一化：把直径缩放到 6cm，保证不同半径下图形视觉大小一致。
\pgfmathsetmacro{\figscale}{3 / \radius}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\Ax}{\radius*cos(\anglea)}
\pgfmathsetmacro{\Ay}{\radius*sin(\anglea)}
\pgfmathsetmacro{\Bx}{\radius*cos(\angleb)}
\pgfmathsetmacro{\By}{\radius*sin(\angleb)}
% 交点 P 按比例取在弦 AB 上（必在圆内），再让弦 CD 过 P，从而保证两弦一定相交
\pgfmathsetmacro{\Px}{\Ax + \pratio*(\Bx - \Ax)}
\pgfmathsetmacro{\Py}{\Ay + \pratio*(\By - \Ay)}
% 过 P 沿方向 chorddir 的直线与圆的两个交点：解 |P + t*u|^2 = radius^2，P 在圆内故两根一正一负
\pgfmathsetmacro{\ux}{cos(\chorddir)}
\pgfmathsetmacro{\uy}{sin(\chorddir)}
\pgfmathsetmacro{\pdotu}{\Px*\ux + \Py*\uy}
\pgfmathsetmacro{\hlen}{sqrt(\pdotu*\pdotu - (\Px*\Px + \Py*\Py) + \radius*\radius)}
\pgfmathsetmacro{\Cx}{\Px + (-\pdotu + \hlen)*\ux}
\pgfmathsetmacro{\Cy}{\Py + (-\pdotu + \hlen)*\uy}
\pgfmathsetmacro{\Dx}{\Px + (-\pdotu - \hlen)*\ux}
\pgfmathsetmacro{\Dy}{\Py + (-\pdotu - \hlen)*\uy}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \draw[thick] (0,0) circle [radius=\radius];
  \draw[thick] ({\Ax},{\Ay}) -- ({\Bx},{\By});
  \draw[thick] ({\Cx},{\Cy}) -- ({\Dx},{\Dy});
  % 相似三角形辅助线：△APC ∽ △DPB
  \ifnum\showsimilar>0
    \draw[thick] ({\Ax},{\Ay}) -- ({\Cx},{\Cy});
    \draw[thick] ({\Dx},{\Dy}) -- ({\Bx},{\By});
  \fi
  % 对顶角 ∠APC 与 ∠BPD
  \ifnum\showangle>0
    \pgfmathsetmacro{\piaax}{\Ax - (\Px)}
    \pgfmathsetmacro{\piaay}{\Ay - (\Py)}
    \pgfmathsetmacro{\piabx}{\Cx - (\Px)}
    \pgfmathsetmacro{\piaby}{\Cy - (\Py)}
    \pgfmathsetmacro{\leniaa}{sqrt((\piaax)^2 + (\piaay)^2)}
    \pgfmathsetmacro{\leniab}{sqrt((\piabx)^2 + (\piaby)^2)}
    \pgfmathsetmacro{\sangia}{atan2(\piaay,\piaax)}
    \pgfmathsetmacro{\erawia}{atan2(\piaby,\piabx)}
    \pgfmathsetmacro{\edifia}{\erawia - \sangia}
    \pgfmathsetmacro{\eangia}{\sangia + \edifia - 360*round(\edifia/360)}
    \pgfmathsetmacro{\arcria}{min(0.4/\figscale, \leniaa*0.3, \leniab*0.3)}
    \draw[thick] ({\Px + \arcria*cos(\sangia)},{\Py + \arcria*sin(\sangia)}) arc[start angle=\sangia, end angle=\eangia, radius=\arcria];
    \pgfmathsetmacro{\pibax}{\Bx - (\Px)}
    \pgfmathsetmacro{\pibay}{\By - (\Py)}
    \pgfmathsetmacro{\pibbx}{\Dx - (\Px)}
    \pgfmathsetmacro{\pibby}{\Dy - (\Py)}
    \pgfmathsetmacro{\leniba}{sqrt((\pibax)^2 + (\pibay)^2)}
    \pgfmathsetmacro{\lenibb}{sqrt((\pibbx)^2 + (\pibby)^2)}
    \pgfmathsetmacro{\sangib}{atan2(\pibay,\pibax)}
    \pgfmathsetmacro{\erawib}{atan2(\pibby,\pibbx)}
    \pgfmathsetmacro{\edifib}{\erawib - \sangib}
    \pgfmathsetmacro{\eangib}{\sangib + \edifib - 360*round(\edifib/360)}
    \pgfmathsetmacro{\arcrib}{min(0.4/\figscale, \leniba*0.3, \lenibb*0.3)}
    \draw[thick] ({\Px + \arcrib*cos(\sangib)},{\Py + \arcrib*sin(\sangib)}) arc[start angle=\sangib, end angle=\eangib, radius=\arcrib];
  \fi
  \ifnum\showcenter>0
    \fill (0,0) circle [radius=\dotr pt];
    \node[below left] at (0,0) {$O$};
  \fi
  \fill ({\Px},{\Py}) circle [radius=\dotr pt];
  % 交点字母偏向圆心一侧的空白处放置，避免压在两条弦上
  \pgfmathsetmacro{\plx}{atan2(\Py,\Px) + 180}
  \node at ({\Px + 0.16*\radius*cos(\plx)},{\Py + 0.16*\radius*sin(\plx)}) {$\labelp$};
  \foreach \lx/\ly/\lb in {\Ax/\Ay/\labela, \Bx/\By/\labelb, \Cx/\Cy/\labelc, \Dx/\Dy/\labeld}{
    \fill ({\lx},{\ly}) circle [radius=\dotr pt];
    \pgfmathsetmacro{\lang}{atan2(\ly,\lx)}
    \node at ({1.16*\radius*cos(\lang)},{1.16*\radius*sin(\lang)}) {$\lb$};
  }
\end{tikzpicture}
